      "card_ids": ["C169", "C163", "C182", "C202", "C164"]
    },
    {
      "claim": "Other L5 records show that related compounds can have high permeability and no appreciable efflux (M06 A-B 2.9 x10^-6 cm/s with B-A 0.1; anlotinib Papp 3.5 x10^-6 cm/s with efflux ratio 0.91; FE Papp 5.28 x10^-6 cm/s with efflux ratio 1.33), and indomethacin, a carboxylic acid, retains moderate permeability with modest efflux (MDCK-MDR1 efflux ratio 1.59), so efflux alone is not affirmative evidence of F < 20%.",
      "card_ids": ["C161", "C190", "C186", "C193"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "contradictory",
